with exploded as (select id, effective_from, currency, explode(tier_prices) as element from price_tiers) select *, rank() over w_hist as element_rank, dense_rank() over w_running as element_dense_rank, rank() over w_running as element_rank_2 from exploded window w_hist as (partition by currency order by element nulls first), w_running as (partition by currency order by element desc nulls first);
